	this.txt.textAlign = "center";
	this.txt.lineHeight = 134;
	this.txt.lineWidth = 1236;
	this.txt.parent = this;
	this.txt.setTransform(-2,-46.05);

	this.txt_6 = new cjs.Text("", "120px 'Passion One'", "#C30808");
	this.txt_6.name = "txt_6";
	this.txt_6.textAlign = "center";
