	this.txt_6.setTransform(-0.75,-44.8);

	this.txt_10 = new cjs.Text("", "120px 'Passion One'", "#801416");
	this.txt_10.name = "txt_10";
	this.txt_10.textAlign = "center";
	this.txt_10.lineHeight = 134;
	this.txt_10.lineWidth = 1236;
	this.txt_10.parent = this;
	this.txt_10.setTransform(0,-44.05);

