	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		this.stop();
		
		const ts = this;
		const incX = 275;
		const incY = 62;
		const ttlW = 800;
		const ttlH = 80;
		var startX = sx = incX/2 + (lg.gameWidth-incX*4)/2;
		var startY = sy = 160;
		var idx = 0;
		const selLang = caller(2, "langCode");
		caller(6, onMouseClick);
		lg.decorateTitle(ts.ttl, {
			key: "langT",
			upper: false,
			scale: true,
			w: ttlW,
			h: ttlH
		});
		let tmpLang = lg.lang;
		
		
		for(var i = 0; i < 9; i++) {
			for(var j = 0; j < 4; j++) {
				if(idx >= lg.codes.length) {
					continue;
				}
				var langSym = new lib.LangSym();
				langSym.x = sx;
				langSym.y = sy;
				langSym.langBtn = true;
				ts.addChild(langSym);
				
				lg.lang = lg.codes[idx];
				lg.setGameFont(langSym.txt, false);
				langSym.flg.font = "40px 'Noto Color Emoji'";
				langSym.name = (lg.codes[idx]);
				let adx = lg.languages[lg.codes[idx]].split(" ");
				let flg = adx.shift();
				let lng = adx.join(" ");
				langSym.flg.text = flg;
				langSym.txt.text = lng;
				langSym.mouseChildren = false;
				langSym.cursor = 'pointer';
				sx += incX;
				if(selLang == langSym.name) {
					langSym.gotoAndStop(1);
				}
				idx++;
			}
			sy += incY;
			sx = startX;
		}
		lg.lang =tmpLang;
		function onMouseClick(e) {
			if(e.target.langBtn == true) {
				ts.getChildByName(lg.lang).gotoAndStop(0);
				lg.lang = e.target.name;
				e.target.gotoAndStop(1);
				lg.decorateTitle(ts.ttl, {
					key: "langT",
					upper: false,
					scale: true,
					w: ttlW,
					h: ttlH
				});
		
			}
			if(e.target.name == "closeBtn") {
				caller(7, onMouseClick);
				caller(4, ts);
				ts.translateParent();
			}
		}
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

