		var graph;
		function getTurnsArr(fClick, sClick) {
			consturctGraph(fClick, sClick);
			var sItem = graph.grid[fClick.tile.row][fClick.tile.col];
			var eItem = graph.grid[sClick.tile.row][sClick.tile.col];
			var result = astar.search(graph, sItem, eItem, {
				turningPenalty: 60
			});
			if(result.length == 0) {
				return {
					turns: null,
					tmp: null
				};
			}
			var tmp_arr = [fClick.tile];
			for(var i = 0; i < result.length; i++) {
				tob = tileObj[result[i].x + "" + result[i].y];
				tmp_arr.push(tob);;
			}
			var turns_arr = calculateTurns(tmp_arr);
			return {
				turns: turns_arr,
				tmp: tmp_arr
			};
		}
		function createGraph(fClick, sClick, kks = false) {
			var obj = getTurnsArr(fClick, sClick);
			var turns_arr = obj.turns;
			var smallArr = turns_arr;
			var tmp_arr = obj.tmp;
			if(turns_arr == null) {
				return null;
			}
			if(kks == true) {
				return turns_arr;
			}
			if(turns_arr.length != 3) {
				return turns_arr;
			} else {
				var tile1 = tmp_arr[1];
				obj = getTurnsArr(sClick, fClick);
				var tile2 = obj.tmp[1];
				turns_arr = obj.turns;
				if(turns_arr.length != 3) {
					return turns_arr.reverse();
				}
				tile1.visible = false;
				tile2.visible = false;
				if(tile1.item == null) {
					tile1.visible = false;
					tile1.item = "jagga";
				}
				var mobj = getTurnsArr(fClick, sClick);
				var mturns_arr = mobj.turns;
				if(mturns_arr != null && mturns_arr.length != 0 && mturns_arr.length < 3) {
					setNull(tmp_arr);
					return mturns_arr;
				}
				mobj = getTurnsArr(fClick, sClick);
				mturns_arr = mobj.turns;
				if(mturns_arr != null && mturns_arr.length != 0 && mturns_arr.length < 3) {
					setNull(tmp_arr);
					return mturns_arr;
				}
				mobj = getTurnsArr(sClick, fClick);
				mturns_arr = mobj.turns;
				if(mturns_arr != null && mturns_arr.length != 0 && mturns_arr.length < 3) {
					setNull(tmp_arr);
					return mturns_arr;
				}
				if(tile2.item == null) {
					tile2.visible = false;
					tile2.item = "jagga";
				}
				mobj = getTurnsArr(sClick, fClick);
				mturns_arr = mobj.turns;
				if(mturns_arr != null && mturns_arr.length != 0 && mturns_arr.length < 3) {
					setNull(tmp_arr);
					return mturns_arr;
				}
			}
			setNull();
			return tmp_arr;
		}
		function setNull() {
			for(var t of tile_arr) {
				if(t.item == "jagga") {
					t.item = null;
					t.visible = true;
				}
			}
		}
		function consturctGraph(fClick, sClick) {
			var arr = []
			var tIdx = 0;
			for(var i = 0; i < totalRows; i++) {
				arr[i] = [];
				for(var j = 0; j < totalCols; j++) {
					tile_arr[tIdx].alpha = 1;
					var item = tile_arr[tIdx].item;
					if(item == null || fClick == item || sClick == item) {
						arr[i][j] = 1;
					} else {
						arr[i][j] = 0;
					}
					tIdx++;
				}
				graph = new Graph(arr);
			}
		}
