		function shuffleAll() {
			for(var i = 0; i < item_arr.length / 2; i++) {
				var idx1 = Math.random() * item_arr.length;
				var idx2 = Math.random() * item_arr.length;
				var itm1 = item_arr[Math.floor(idx1)];
				var itm2 = item_arr[Math.floor(idx2)];
				var tmp = {
					t: itm1.tile,
					x: itm1.x,
					y: itm1.y
				};
				itm1.tile = itm2.tile;
				itm1.x = itm2.x;
				itm1.y = itm2.y;
				itm2.x = tmp.x;
				itm2.y = tmp.y;
				itm2.tile = tmp.t;
				itm1.tile.item = itm1;
				itm2.tile.item = itm2;
			}
		}
