		function initLevel() {
			var sx = startXPos;
			var sy = startYPos;
			var idxx = 0;
			var frmss = 0;
			for(var i = 0; i < totalRows; i++) {
				for(var j = 0; j < totalCols; j++) {
					var tile = {};
					tile.item = null;
					tile.row = i;
					tile.col = j;
					tileObj[i + "" + j] = tile;
					if(lItemPos[idxx] != 0) {
						var itm = new lib.Items();
						itm.downS = 1;
						itm.name = "MahjongItem" + frmss;
						itm.gotoAndStop(itemFrameNumbers[frmss]);
						frmss++;
						itm.x = sx;
						tile.item = itm;
						itm.tile = tile;
						itm.y = sy;
						itemContainer.addChild(itm);
						item_arr.push(itm);
						dupArr.push(itm);
						initItem(itm);
		
		
					}
					tile.x = sx;
					tile.y = sy;
					tile_arr.push(tile);
					sx += xDifference;
					idxx++;
				}
				sx = startXPos;
				sy += yDifference;
			}
		}
		
		function calculateTurns(arr) {
			if(arr.length == 0) {
				return null;
			}
			var turn = 0;
			var xsame = true;
			var ysame = true;
			var tmp_arr = [];
			for(var i = 0; i < arr.length - 1; i++) {
				var fobj = arr[i];
				var sobj = arr[i + 1];
				if(fobj.x == sobj.x) {
					if(!xsame) {
						xsame = true;
						tmp_arr.push(fobj);
						turn++;
					}
				} else {
					xsame = false;
				}
				if(fobj.y == sobj.y) {
					if(!ysame) {
						ysame = true;
						tmp_arr.push(fobj);
						turn++;
					}
				} else {
					ysame = false;
				}
			}
			return tmp_arr;
		}
