		lg.intiParticleMC = function(mcClass, num, pClass, pos, gvt = 4) {
			var pmc = new createjs.Container();
			pClass.addChild(pmc);
			pmc.x = pos.x;
			pmc.y = pos.y;
			caller(26, runParticles);
			var part_Array = [];
			for(var i = 0; i < num; i++) {
				var part = new lib[mcClass];
				pmc.addChild(part);
				part_Array.push(part);
				part.gotoAndStop(Math.floor(Math.random() * 10));
				part.vx = Math.round(-12 + Math.random() * 24);
				part.vy = Math.round(-15 + Math.random() * -15);
				part.gravity = gvt;
			}
			function runParticles(e) {
				for(var i = part_Array.length - 1; i >= 0; i--) {
					var part = part_Array[i];
					part.x += part.vx;
					part.y += part.vy;
					part.vy += part.gravity;
					part.rotation += part.vx;
					part.alpha -= 0.001;
					part.scaleX = part.scaleY = part.scaleX * 1.001;
					if(part.vy > 10) {
						part.alpha -= 0.1;
						part.scaleX = part.scaleY = part.scaleX * 1.1;
					}
					if(part.alpha == 0 || part.y > 450) {
						pmc.removeChild(part);
						part_Array.splice(part_Array.indexOf(part), 1);
					}
				}
				if(part_Array.length == 0) {
					caller(27, runParticles);
					if(pmc.parent) {
						pmc.parent.removeChild(pmc);
		
					}
				}
			}
		};
